function bannerList(){return state.banners??[{eyebrow:'TECNOLOGIA QUE VOLTA A FUNCIONAR',title:state.settings.headline,highlight:state.settings.highlight,description:state.settings.description,image:state.settings.heroImage,buttonText:'Preciso de assistência',destination:'services'}]}
function renderBanners(){const list=bannerList();$('#admin-banners').innerHTML=list.map((b,i)=>'<article class="admin-row"><img src="'+esc(b.image)+'" alt=""><div class="details"><h3>'+(i+1)+'. '+esc(b.title)+'</h3><p>'+esc(b.highlight)+'</p></div><div class="row-actions"><button data-banner-edit="'+i+'">Editar</button><button data-banner-up="'+i+'" '+(i===0?'disabled':'')+'>Mover para cima</button><button data-banner-delete="'+i+'" class="danger" '+(list.length===1?'disabled':'')+'>Excluir</button></div></article>').join('');$('#new-banner').disabled=list.length>=8}
function editBanner(index){const f=$('#banner-form');f.reset();f.querySelector('.editor-error').textContent='';const b=bannerList()[index]||{eyebrow:'',title:'',highlight:'',description:'',image:'',buttonText:'Ver produtos',destination:'products'};formValue(f,'index').value=index??'';for(const key of ['eyebrow','title','highlight','description','image','buttonText','destination'])formValue(f,key).value=b[key];$('#banner-photo-preview').src=b.image;$('#banner-photo-preview').hidden=!b.image;$('#banner-editor').showModal()}
$('#new-banner').onclick=()=>editBanner();
document.addEventListener('click',async event=>{const b=event.target.closest('[data-banner-edit],[data-banner-up],[data-banner-delete]');if(!b||busy)return;try{if(b.dataset.bannerEdit!==undefined)editBanner(Number(b.dataset.bannerEdit));if(b.dataset.bannerUp!==undefined){const i=Number(b.dataset.bannerUp);if(i<1)return;const next=structuredClone(state);next.banners=structuredClone(bannerList());[next.banners[i-1],next.banners[i]]=[next.banners[i],next.banners[i-1]];await save(next)}if(b.dataset.bannerDelete!==undefined)confirmAction('Excluir este destaque da página inicial?',async()=>{const next=structuredClone(state);next.banners=structuredClone(bannerList());next.banners.splice(Number(b.dataset.bannerDelete),1);await save(next)})}catch(e){message(e.message,true)}});
$('#banner-form').onsubmit=async event=>{event.preventDefault();const f=event.target;try{const data=Object.fromEntries(new FormData(f));const index=data.index;delete data.index;const next=structuredClone(state);next.banners=structuredClone(bannerList());if(index==='')next.banners.push(data);else next.banners[Number(index)]=data;await save(next);$('#banner-editor').close()}catch(e){f.querySelector('.editor-error').textContent=e.message}};
formValue($('#banner-form'),'image').addEventListener('input',event=>{const value=event.target.value;const preview=$('#banner-photo-preview');if(/^https:\/\//.test(value)||value.startsWith('/media/')){preview.src=value;preview.hidden=false}});
